def emit(rec):
    assert set(rec.keys()) == {"case_id", "prediction_text", "basis", "confidence", "trigger"}, rec["case_id"]
    assert isinstance(rec["confidence"], float) and 0.0 <= rec["confidence"] <= 1.0
    assert set(rec["trigger"].keys()) == {"changed_main", "reserve_used", "disputed", "reason"}
    p = OUT / (rec["case_id"] + ".json")
    p.write_text(json.dumps(rec, ensure_ascii=False, indent=1), encoding="utf-8")
    back = json.loads(p.read_text(encoding="utf-8"))
    assert back["case_id"] == rec["case_id"] and back["prediction_text"] == rec["prediction_text"]
